solution.solution.c:
#include <stdbool.h>

const char *grade(int score)
{
    if (score >= 90) return "A";
    if (score >= 80) return "B";
    if (score >= 70) return "C";
    if (score >= 60) return "D";
    return "F";
}

bool is_leap(int year)
{
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

int days_in_month(int month, int year)
{
    switch (month) {
    case 1: case 3: case 5: case 7: case 8: case 10: case 12:
        return 31;
    case 4: case 6: case 9: case 11:
        return 30;
    case 2:
        return is_leap(year) ? 29 : 28;
    default:
        return 0;
    }
}

const char *kind_of(char c)
{
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) return "letter";
    if (c >= '0' && c <= '9') return "digit";
    if (c == ' ' || c == '\t' || c == '\n') return "space";
    return "other";
}

unitTests:
TEST("grades at the edges") { CHECK_EQ(grade(100), "A"); CHECK_EQ(grade(90), "A"); CHECK_EQ(grade(89), "B"); CHECK_EQ(grade(70), "C"); CHECK_EQ(grade(60), "D"); CHECK_EQ(grade(59), "F"); CHECK_EQ(grade(0), "F"); }
TEST("leap years") { CHECK(is_leap(2024)); CHECK(!is_leap(2023)); CHECK(!is_leap(1900)); CHECK(is_leap(2000)); }
TEST("days in a month") { CHECK_EQ(days_in_month(1, 2023), 31); CHECK_EQ(days_in_month(4, 2023), 30); CHECK_EQ(days_in_month(2, 2023), 28); CHECK_EQ(days_in_month(2, 2024), 29); CHECK_EQ(days_in_month(12, 2023), 31); CHECK_EQ(days_in_month(13, 2023), 0); CHECK_EQ(days_in_month(0, 2023), 0); }
TEST("kinds of character") { CHECK_EQ(kind_of('q'), "letter"); CHECK_EQ(kind_of('Q'), "letter"); CHECK_EQ(kind_of('7'), "digit"); CHECK_EQ(kind_of(' '), "space"); CHECK_EQ(kind_of('\n'), "space"); CHECK_EQ(kind_of('?'), "other"); }

